{
  "name": "magpie-ctyun",
  "version": "0.3.1",
  "description": "天翼云息壤「ctyun」Coding Plan 的 MAGPIE 供应商插件，支持仅 API Key 接入、可选网页登录、模型发现与原生额度窗口。",
  "type": "module",
  "main": "./index.mjs",
  "exports": "./index.mjs",
  "files": [
    "index.mjs",
    "src/",
    "README.md",
    "CHANGELOG.md",
    "LICENSE",
    "SECURITY.md",
    "ACCOUNT_DELETION.md",
    "THIRD_PARTY_NOTICES.md",
    "scripts/forget-credentials.mjs"
  ],
  "scripts": {
    "test": "node --test test/*.test.mjs",
    "check": "node --check index.mjs && node --check src/session.mjs && node --check src/browser.mjs && node --check src/plugin.mjs && node --check src/model-profiles.mjs && node --check src/sse.mjs",
    "test:live": "node scripts/live-check.mjs",
    "browser:install": "playwright install chromium",
    "credentials:forget": "node scripts/forget-credentials.mjs",
    "test:browser": "node scripts/browser-smoke.mjs"
  },
  "engines": {
    "node": ">=22"
  },
  "keywords": [
    "magpie",
    "opencode-plugin",
    "ctyun",
    "coding-plan"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sheauhuu/magpie-ctyun-coding-plan.git",
    "directory": "."
  },
  "license": "MIT",
  "dependencies": {
    "tough-cookie": "^6.0.2"
  },
  "optionalDependencies": {
    "@napi-rs/keyring": "^2.1.2",
    "playwright": "^1.64.1"
  },
  "magpie": {
    "maxConcurrency": 4,
    "icon": "data:image/png;base64,",
    "name": "天翼云息壤「ctyun」",
    "summary": {
      "en": "Unofficial 天翼云息壤「ctyun」Coding Plan provider for magpie: API key sign-in, optional browser/password login, official model discovery and native quota windows.",
      "zh": "非官方天翼云息壤「ctyun」Coding Plan 接入：支持仅 API Key 调用模型，可选密码登录或浏览器单点登录以获取官方模型发现与 5 小时／周／套餐总量三个额度窗口。"
    }
  }
}
